def _row(m, specs):
    """A terrace of buildings side by side along x (corner shop row)."""
    bx = m.bx
    parts = []
    x = 0.0
    total = sum(s[0] for s in specs)
    x = -total / 2.0
    for w, d, h, wall, roof, floors, cols in specs:
        cx = x + w / 2.0
        parts.append(bx((cx, 0, h / 2), (w, d, h), wall))
        parts.append(bx((cx, 0, h + 0.2), (w + 0.2, d + 0.4, 0.4), roof))
        for f in range(floors):
            for c in range(cols):
                parts.append(bx((cx - w / 2 + w * (c + 0.5) / cols, -d / 2 - 0.03, h * (f + 0.65) / floors), (w / cols * 0.4, 0.08, h / floors * 0.35), "w-glass"))
        parts.append(bx((cx, -d / 2 - 0.1, 1.1), (1.8, 0.15, 2.2), "w-door"))
        parts.append(bx((cx, -d / 2 - 0.6, 3.1), (w * 0.8, 1.2, 0.2), "w-accent-red" if len(parts) % 2 else "w-accent-teal"))
        x += w
    return parts


def _glass_tower(m, bow):
    bx, cy, sp = m.bx, m.cy, m.sp
    parts = [bx((0, 0, 30.0), (12.0, 12.0, 60.0), "w-glass")]
    for i in range(1, 12):
        parts.append(bx((0, 0, 5.0 * i), (12.3, 12.3, 0.3), "w-metal"))
    for x in (-6.0, 6.0):
        for y in (-6.0, 6.0):
            parts.append(bx((x, y, 30.0), (0.5, 0.5, 60.0), "w-metal-dark"))
    parts.append(bx((0, 0, 60.4), (10.0, 10.0, 0.8), "w-metal-dark"))
    parts.append(cy((0, 0, 63.0), 0.2, 6.0, "w-metal", 6))
    if bow:
        # Giant red ribbon: two bands over the roof and down the faces, and a bow on top.
        red = "w-accent-red"
        parts += [bx((0, 0, 30.0), (12.5, 1.6, 60.2), red), bx((0, 0, 30.0), (1.6, 12.5, 60.2), red),
                  sp((-2.6, 0, 62.4), 2.2, red, (1.5, 0.9, 0.8), 1), sp((2.6, 0, 62.4), 2.2, red, (1.5, 0.9, 0.8), 1), sp((0, 0, 62.0), 1.0, red, (), 1)]
    return parts
